// fp-ts — Option (= Maybe)
import { pipe } from 'fp-ts/function';
import * as O from 'fp-ts/Option';

const result = pipe(
  O.fromNullable(findUser(1)),
  O.flatMap(u => O.fromNullable(getAddress(u))),
  O.map(a => a.postalCode),
  O.getOrElse(() => "N/A")
);

